#!/usr/bin/env python3
"""Warn when file systems are fuller than a limit."""
import argparse
import json
import shutil
import sys


def parse_args(argv=None):
    parser = argparse.ArgumentParser(
        description="Check how full file systems are.",
        epilog="Example: ./diskcheck.py / /home --warn 80",
    )
    parser.add_argument("paths", nargs="+", help="mount points or directories to check")
    parser.add_argument("--warn", type=int, default=90, metavar="PERCENT",
                        help="warn when more than this percentage is used (default: %(default)s)")
    parser.add_argument("--format", choices=["text", "json"], default="text", help="output format")
    parser.add_argument("-q", "--quiet", action="store_true", help="print only problems")
    args = parser.parse_args(argv)
    if not 1 <= args.warn <= 100:
        parser.error("--warn must be between 1 and 100")
    return args


def main() -> int:
    args = parse_args()
    results = []
    for path in args.paths:
        usage = shutil.disk_usage(path)
        percent = round(usage.used / usage.total * 100)
        results.append({"path": path, "used_percent": percent, "ok": percent <= args.warn})
    if args.format == "json":
        print(json.dumps(results))
    else:
        for r in results:
            if not (args.quiet and r["ok"]):
                print(f"{'OK  ' if r['ok'] else 'FULL'} {r['path']}: {r['used_percent']}% used")
    return 0 if all(r["ok"] for r in results) else 1


if __name__ == "__main__":
    sys.exit(main())

