"""Read the shop's log lines: TIME LEVEL SERVICE key=value key=value ..."""
from collections.abc import Iterable, Iterator
from dataclasses import dataclass, field
from pathlib import Path

LEVELS = {"DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"}


@dataclass
class Entry:
    time: str
    level: str
    service: str
    fields: dict[str, str] = field(default_factory=dict)

    @property
    def duration_ms(self) -> int:
        return int(self.fields.get("duration_ms", "0"))


def parse_line(line: str) -> Entry | None:
    """Turn one log line into an Entry, or None if it isn't a log line."""
    parts = line.split()
    if len(parts) < 3 or parts[1] not in LEVELS:
        return None
    time, level, service, *rest = parts
    fields = dict(item.split("=", 1) for item in rest if "=" in item)
    return Entry(time, level, service, fields)


def read_entries(paths: Iterable[Path]) -> Iterator[Entry]:
    """Every log entry in the files, in order; lines that aren't log lines are skipped."""
    for path in paths:
        with Path(path).open(encoding="utf-8") as f:
            for line in f:
                entry = parse_line(line)
                if entry is not None:
                    yield entry

