    """Count the lines at each level in FILES."""
    counts = Counter(e.level for e in read_entries(files))
    if not counts:
        raise click.ClickException("no log lines found in " + ", ".join(f.name for f in files))
    for level in LEVELS:
        click.echo(f"{level:<8}{counts.get(level, 0):>5}")


