#!/usr/bin/env python3
"""Summarise request durations from log lines on standard input."""
import statistics
import sys


def main() -> int:
    durations = []
    for line in sys.stdin:
        for field in line.split():
            if field.startswith("duration_ms="):
                durations.append(int(field.removeprefix("duration_ms=")))
    if not durations:
        print("no durations found", file=sys.stderr)
        return 1
    p95 = statistics.quantiles(durations, n=20)[-1]
    print(f"requests={len(durations)} mean={statistics.mean(durations):.0f}ms "
          f"p95={p95:.0f}ms max={max(durations)}ms")
    return 0


if __name__ == "__main__":
    sys.exit(main())

import json, shutil, subprocess

def run(cmd):
    """Run a command and return its standard output; raise if it fails."""
    return subprocess.run(cmd, capture_output=True, text=True, check=True, timeout=10).stdout

def run_json(cmd):
    return json.loads(run(cmd))

