"""The devsetup command: plan, apply and check a developer machine against a profile."""
import logging
import tomllib
from dataclasses import dataclass
from pathlib import Path

import click

log = logging.getLogger("devsetup")


@dataclass
class Profile:
    packages: list[str]
    directories: list[Path]
    files: dict[Path, str]


def load_profile(path: Path) -> Profile:
    """Read a profile. ~ in its paths means the user's home folder."""
    try:
        with path.open("rb") as f:
            data = tomllib.load(f)
        base = Path(data["directories"]["base"]).expanduser()
        return Profile(
            packages=list(data.get("packages", {}).get("apt", [])),
            directories=[base / name for name in data["directories"].get("create", [])],
            files={Path(item["path"]).expanduser(): item["content"] for item in data.get("files", [])},
        )
    except FileNotFoundError:
        raise click.ClickException(f"profile not found: {path}")
    except (KeyError, tomllib.TOMLDecodeError) as e:
        raise click.ClickException(f"bad profile {path}: {e}")


@click.group()
@click.version_option("0.1.0", prog_name="devsetup")
@click.option("--profile", "profile_path", type=click.Path(dir_okay=False, path_type=Path),
              default="profile.toml", show_default=True, envvar="DEVSETUP_PROFILE",
              help="The profile to use (or set DEVSETUP_PROFILE).")
